import re

from moler.exceptions import ParsingDone
from moler.helpers import convert_to_number

from ta_moler.cmd.egate.genericepcsim import GenericEPCSIMCommand


class Bcmdiag(GenericEPCSIMCommand):
    """Command bcmdiag."""

    def __init__(self, connection, options=None, prompt=None, newline_chars=None, runner=None):
        """
        Command bcmdiag.

        :param connection: moler connection to device, terminal when command is executed
        :param options: Options of bcmdiag command.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Bcmdiag, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self.column_names = [
            "port",
            "port_nr",
            "ena_link",
            "speed",
            "duplex",
            "scan",
            "auto_neg",
            "STP_state",
            "pause",
            "discard",
            "lrn_ops",
            "interface",
            "max_frame",
            "loopback",
        ]

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = f"bcmdiag {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_bcmdiag(line)
            except ParsingDone:
                pass
        return super(Bcmdiag, self).on_new_line(line, is_full_line)

    #        ge0( 10)  down    1G  FD   SW  Yes  Forward  TX RX   None   FA   GMII  9500
    _re_bcmdiag = re.compile(
        r"(?P<PORT>\S+)\(\s+(?P<PORT_NR>\d+)\)\s+(?P<ENA_LINK>\S+)\s+(?P<SPEED>\S+)\s+(?P<DUPLEX>\S+)\s+(?P<SCAN>\S+)\s+(?P<AUTO_NEG>\S+)\s+(?P<STP_STATE>\S+)\s+(?P<PAUSE>\S*\s\S*)\s+(?P<DISCARD>\S+)\s+(?P<LRN_OPS>\S+)\s+(?P<INTERFACE>\S+)\s+(?P<MAX_FRAME>\d+)\s?(?P<LOOPBACK>\S?)"
    )

    def _parse_bcmdiag(self, line):
        if self._regex_helper.search_compiled(Bcmdiag._re_bcmdiag, line):
            self.current_ret[self._regex_helper.group(self.column_names[0].upper())] = {}
            for column in self.column_names:
                self.current_ret[self._regex_helper.group(self.column_names[0].upper())][column] = convert_to_number(
                    self._regex_helper.group(column.upper())
                )

            raise ParsingDone


